#include <bits/stdc++.h>
using namespace std;

class GameSolver {
public:
    int minDiff;

    void evaluate(vector<vector<int>> &pairs, vector<int> a, vector<int> b) {
        for (auto &p : pairs) {
            int m = min(a[p[0]], b[p[1]]);
            b[p[1]] -= m;
            a[p[0]] -= m;
        }
        int total = 0;
        for (int val : a) total += val;
        minDiff = min(minDiff, total);
    }

    void generate(vector<vector<int>> &pairs, int idx, vector<int> a, vector<int> b) {
        evaluate(pairs, a, b);
        for (int i = idx; i < (int)pairs.size(); i++) {
            swap(pairs[i], pairs[idx]);
            generate(pairs, idx + 1, a, b);
            swap(pairs[i], pairs[idx]);
        }
    }

